":"Service","name":"Homeowner Claim Appraisal","url":"https://washingtoninsuranceappraiser.com/insurance-appraisal-services/home-insurance-claim-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Condo, HOA & Commercial Appraisal","url":"https://washingtoninsuranceappraiser.com/insurance-appraisal-services/condo-hoa-commercial-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Roof & Hail Damage Appraisal","url":"https://washingtoninsuranceappraiser.com/insurance-appraisal-services/roof-hail-damage-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Windstorm & Tornado Appraisal","url":"https://washingtoninsuranceappraiser.com/insurance-appraisal-services/windstorm-tornado-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Fallen Tree Damage Appraisal","url":"https://washingtoninsuranceappraiser.com/insurance-appraisal-services/tree-impact-claim-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Water & Rain Intrusion Appraisal","url":"https://washingtoninsuranceappraiser.com/insurance-appraisal-services/water-rain-intrusion-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Fire & Smoke Damage Appraisal","url":"https://washingtoninsuranceappraiser.com/insurance-appraisal-services/house-fire-smoke-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Wildfire & Ash Claim Appraisal","url":"https://washingtoninsuranceappraiser.com/insurance-appraisal-services/wildfire-ash-claim-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Snow, Ice Dam & Freeze Appraisal","url":"https://washingtoninsuranceappraiser.com/insurance-appraisal-services/snow-ice-freeze-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Carrier Estimate Review","url":"https://washingtoninsuranceappraiser.com/insurance-appraisal-services/carrier-estimate-review/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Neutral Umpire Services","url":"https://washingtoninsuranceappraiser.com/insurance-appraisal-services/neutral-umpire-services/"}}]},"knowsAbout":["Insurance appraisal","Appraisal clause","Property claim valuation","Windstorm damage","Wildfire claims","Xactimate estimating"],"openingHoursSpecification":[{"@type":"OpeningHoursSpecification","dayOfWeek":["Monday","Tuesday","Wednesday","Thursday","Friday"],"opens":"08:00","closes":"18:00"}]},{"@type":"WebSite","@id":"https://washingtoninsuranceappraiser.com/#website","url":"https://washingtoninsuranceappraiser.com/","name":"Washington Insurance Appraiser","publisher":{"@id":"https://washingtoninsuranceappraiser.com/#business"},"inLanguage":"en-US"},{"@type":"WebPage","@id":"https://washingtoninsuranceappraiser.com/how-insurance-appraisal-works/#webpage","url":"https://washingtoninsuranceappraiser.com/how-insurance-appraisal-works/","name":"How Insurance Appraisal Works in Washington | 7 Steps","description":"A step-by-step guide to insurance appraisal in Washington: the written demand, choosing appraisers and an umpire, and the binding award.","inLanguage":"en-US","isPartOf":{"@id":"https://washingtoninsuranceappraiser.com/#website"},"about":{"@id":"https://washingtoninsuranceappraiser.com/#business"},"publisher":{"@id":"https://washingtoninsuranceappraiser.com/#business"},"dateModified":"2026-11-13","breadcrumb":{"@id":"https://washingtoninsuranceappraiser.com/how-insurance-appraisal-works/#breadcrumb"},"primaryImageOfPage":{"@type":"ImageObject","@id":"https://washingtoninsuranceappraiser.com/how-insurance-appraisal-works/#primaryimage","url":"https://washingtoninsuranceappraiser.com/assets/img/photos/clipboard-inspection.webp","width":1200,"height":800,"caption":"Clipboard with blank paper on a wooden desk between two small potted plants"},"mainEntity":{"@id":"https://washingtoninsuranceappraiser.com/how-insurance-appraisal-works/#howto"}},{"@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":"https://washingtoninsuranceappraiser.com/"},{"@type":"ListItem","position":2,"name":"How appraisal works","item":"https://washingtoninsuranceappraiser.com/how-insurance-appraisal-works/"}],"@id":"https://washingtoninsuranceappraiser.com/how-insurance-appraisal-works/#breadcrumb"},{"@type":"HowTo","name":"How insurance appraisal works in Washington","description":"The seven steps of a property insurance appraisal, from written demand to signed award.","step":[{"@type":"HowToStep","position":1,"name":"Put the disagreement on paper","text":"Appraisal starts with a claim the insurer has accepted at least in part. Before anything formal happens, write down what you think the estimate misses, attach your contractor’s figures and photos, and ask the adjuster to reconsider. Insurers in Washington are expected to respond to claim communications promptly under the state’s claims-handling rules, and many gaps close at this stage through a supplement.","url":"https://washingtoninsuranceappraiser.com/how-insurance-appraisal-works/#step-1"},{"@type":"HowToStep","position":2,"name":"Send the written demand","text":"If the gap remains, either side may demand appraisal in writing. A clear demand identifies the claim, says the parties disagree on the amount of loss, invokes the appraisal condition and names your appraiser or commits to naming one within the policy’s time frame. Send it in a way you can prove, such as email plus certified mail. Check first whether the policy requires a sworn proof of loss or other step.","url":"https://washingtoninsuranceappraiser.com/how-insurance-appraisal-works/#step-2"},{"@type":"HowToStep","position":3,"name":"Each side names an appraiser","text":"Each party picks a competent, independent appraiser, often within 20 days of the demand. Your appraiser inspects the property, studies the file and builds a line-item valuation. The insurer’s appraiser does the same. The two exchange estimates and start working through the differences.","url":"https://washingtoninsuranceappraiser.com/how-insurance-appraisal-works/#step-3"},{"@type":"HowToStep","position":4,"name":"The appraisers choose an umpire","text":"The two appraisers agree on a neutral umpire, ideally early so one is ready if needed. If they can’t agree within the time the policy allows, commonly 15 days, either side can ask a court of record in the county where the property is located to appoint one. In Washington, that is usually the superior court.","url":"https://washingtoninsuranceappraiser.com/how-insurance-appraisal-works/#step-4"},{"@type":"HowToStep","position":5,"name":"The appraisers work the numbers","text":"Most of the work happens here. The appraisers walk the property together, compare measurements and pricing, and agree on as many line items as they can. Many appraisals end at this stage with both appraisers signing an agreed award, and no umpire decision is needed.","url":"https://washingtoninsuranceappraiser.com/how-insurance-appraisal-works/#step-5"},{"@type":"HowToStep","position":6,"name":"The umpire decides what’s left","text":"Items the appraisers can’t settle go to the umpire. Each appraiser submits a position with supporting evidence. The umpire may inspect, ask questions or hold an informal meeting, then decides each disputed item.","url":"https://washingtoninsuranceappraiser.com/how-insurance-appraisal-works/#step-6"},{"@type":"HowToStep","position":7,"name":"The award is signed and paid","text":"An award signed by any two of the three sets the amount of loss. A good award separates replacement cost, depreciation and actual cash value by coverage. The insurer then pays under the policy, less the deductible and earlier payments, with recoverable depreciation paid once repairs are done.","url":"https://washingtoninsuranceappraiser.com/how-insurance-appraisal-works/#step-7"}],"@id":"https://washingtoninsuranceappraiser.com/how-insurance-appraisal-works/#howto"}]}</script>
</head>
